const ollamaResponse = $input.all()[0].json;
let ollamaStatus = 'desconectado';
let modelos = [];

try {
  if (ollamaResponse && ollamaResponse.models) {
    ollamaStatus = 'conectado';
    modelos = ollamaResponse.models.map(m => m.name);
  }
} catch(e) {
  ollamaStatus = 'error: ' + e.message;
}

const reporte = {
  timestamp: new Date().toISOString(),
  sistema: {
    n8n: 'operativo',
    ollama: ollamaStatus,
    modelos_disponibles: modelos
  },
  checks: {
    n8n_respondiendo: true,
    ollama_conectado: ollamaStatus === 'conectado',
    llama3_disponible: modelos.some(m => m.includes('llama3')),
    embeddings_disponible: modelos.some(m => m.includes('nomic-embed-text'))
  },
  resumen: ollamaStatus === 'conectado' ? 'Sistema operativo' : 'Ollama no disponible - verificar que esté corriendo'
};

return [{ json: reporte }];

return [{
  json: {
    timestamp: new Date().toISOString(),
    sistema: {
      n8n: 'operativo',
      ollama: 'desconectado'
    },
    checks: {
      n8n_respondiendo: true,
      ollama_conectado: false,
      llama3_disponible: false,
      embeddings_disponible: false
    },
    resumen: 'Ollama no está corriendo. Ejecutá: ollama serve',
    solucion: 'Verificar que Ollama esté instalado y corriendo en localhost:11434'
  }
}];
